insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('97515673-cc04-45b7-b15c-9bd0b82cb9ed', '677ae388-ce8a-4c81-8916-b659c93f61a3', 1,
   '[{"domain": "Markt", "subdomain": "Kostenstructuur en opbrengsten"}]'::jsonb,
   '["constante kosten", "vaste kosten", "variabele kosten", "kostenstructuur"]'::jsonb,
   $$Een voorbeeld geven van constante kosten en uitleggen waarom deze kosten constant zijn.$$,
   $$economie-havo-2018-ii-brabantse-nachten-zijn-lang-vraag1.png$$, $$2p 1 Geef een voorbeeld van vaste (constante) kosten van de Brabantse Avond en licht toe waarom deze kosten constant zijn.$$, array['660df153-051a-4678-a25f-bb4eb3a43ec4']::uuid[]),
  ('0529a392-8f5a-4064-ad82-ad451676ccc7', '677ae388-ce8a-4c81-8916-b659c93f61a3', 2,
   '[{"domain": "Markt", "subdomain": "Producentengedrag"}]'::jsonb,
   '["prijsdiscriminatie", "voorwaarden prijsdiscriminatie", "gescheiden markten", "betalingsbereidheid"]'::jsonb,
   $$Noemen van twee voorwaarden om prijsdiscriminatie te kunnen toepassen.$$,
   $$economie-havo-2018-ii-brabantse-nachten-zijn-lang-vraag2.png$$, $$Gebruik de uitspraak van de voorzitter.
